SELECT set_config('request.jwt.claim.role','service_role',false);
SELECT set_config('request.jwt.claim.sub','f49d6153-1835-4455-81f3-2918d5d3484e',false);
BEGIN;
INSERT INTO public.qb_questions (subject_id, difficulty, question_type, question_text, options, correct_answer, explanation, points, tags) VALUES
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'intermediate', 'multiple_choice', 'What is the primary reason cotton fiber is measured for ''fiber strength'' (e.g., in grams per tex) as a distinct property from staple length?', '["A fiber can be long but weak (or short but strong); yarn strength depends on both fiber length (for grip/friction) and individual fiber strength (for load-bearing), so both must be assessed separately","Fiber strength and staple length are always perfectly correlated, so measuring one automatically tells you the other","Fiber strength has no relationship to the resulting yarn''s strength at all","Only staple length matters for yarn quality; fiber strength is an irrelevant, unmeasured property"]'::jsonb, 'A fiber can be long but weak (or short but strong); yarn strength depends on both fiber length (for grip/friction) and individual fiber strength (for load-bearing), so both must be assessed separately', 'Fiber length and fiber strength are independent properties — a cotton variety could have long staple but weak individual fibers (or vice versa) — and since yarn strength depends on both adequate fiber-to-fiber friction/length AND the individual fiber''s own tenacity, both properties are measured and specified separately in cotton quality assessment.', 2, '{"fiber-strength"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'intermediate', 'multiple_choice', 'What does ''short fiber index'' (or short fiber content) measure in a cotton fiber quality assessment?', '["The percentage of fibers in a sample below a certain defined short length threshold, which tends to increase processing waste and reduce yarn quality","The exact color grade of the cotton sample","The total moisture content of the raw fiber bale","The twist level already present in the raw fiber before spinning"]'::jsonb, 'The percentage of fibers in a sample below a certain defined short length threshold, which tends to increase processing waste and reduce yarn quality', 'Short fiber content/index quantifies the proportion of fibers shorter than a defined threshold within a sample; higher short-fiber content generally means more processing waste (noil), more neps, and reduced achievable yarn quality/strength for a given average staple length.', 2, '{"short-fiber-content"}'::text[]),
('9dc3ade3-26ea-41fa-a83f-95a7440889b8', 'intermediate', 'multiple_choice', 'Why might two cotton samples with the IDENTICAL average staple length still spin very differently, in terms of achievable yarn quality?', '["They could differ in short fiber content, fiber strength, maturity, or fineness — properties not captured by average staple length alone","Average staple length alone always fully determines spinning performance with no other relevant factor","Two samples with identical average staple length must, by definition, have identical fiber-length distribution and all other properties","There is no such thing as a fiber property other than average staple length"]'::jsonb, 'They could differ in short fiber content, fiber strength, maturity, or fineness — properties not captured by average staple length alone', 'Average staple length is just one summary statistic; two samples could share the same average yet differ significantly in fiber-length distribution (short fiber content), individual fiber strength, maturity, and fineness — all of which independently affect spinning performance and yarn quality potential.', 2, '{"fiber-quality-factors"}'::text[]);
COMMIT;
